// jQuery 模拟库 - 仅用于演示
// 实际项目中应使用完整版 jQuery
(function(window) {
    var jQuery = function(selector) {
        return new jQuery.fn.init(selector);
    };
    
    jQuery.fn = jQuery.prototype = {
        init: function(selector) {
            if (!selector) return this;
            
            if (typeof selector === 'string') {
                // 简单模拟选择器
                if (selector.charAt(0) === '#') {
                    this[0] = document.getElementById(selector.substring(1));
                } else if (selector.charAt(0) === '.') {
                    var elements = document.getElementsByClassName(selector.substring(1));
                    for (var i = 0; i < elements.length; i++) {
                        this[i] = elements[i];
                    }
                } else {
                    var elements = document.getElementsByTagName(selector);
                    for (var i = 0; i < elements.length; i++) {
                        this[i] = elements[i];
                    }
                }
                this.length = elements ? elements.length : 1;
            } else if (selector.nodeType) {
                this[0] = selector;
                this.length = 1;
            }
            
            return this;
        },
        
        length: 0,
        
        ready: function(callback) {
            if (document.readyState === "complete") {
                callback();
            } else {
                document.addEventListener('DOMContentLoaded', callback);
            }
            return this;
        },
        
        click: function(callback) {
            for (var i = 0; i < this.length; i++) {
                this[i].addEventListener('click', callback);
            }
            return this;
        },
        
        keypress: function(callback) {
            for (var i = 0; i < this.length; i++) {
                this[i].addEventListener('keypress', callback);
            }
            return this;
        },
        
        submit: function(callback) {
            for (var i = 0; i < this.length; i++) {
                this[i].addEventListener('submit', callback);
            }
            return this;
        },
        
        val: function(value) {
            if (value === undefined) {
                return this[0] ? this[0].value : '';
            } else {
                for (var i = 0; i < this.length; i++) {
                    this[i].value = value;
                }
                return this;
            }
        },
        
        text: function(text) {
            if (text === undefined) {
                return this[0] ? this[0].textContent : '';
            } else {
                for (var i = 0; i < this.length; i++) {
                    this[i].textContent = text;
                }
                return this;
            }
        },
        
        html: function(html) {
            if (html === undefined) {
                return this[0] ? this[0].innerHTML : '';
            } else {
                for (var i = 0; i < this.length; i++) {
                    this[i].innerHTML = html;
                }
                return this;
            }
        },
        
        show: function() {
            for (var i = 0; i < this.length; i++) {
                this[i].style.display = '';
            }
            return this;
        },
        
        hide: function() {
            for (var i = 0; i < this.length; i++) {
                this[i].style.display = 'none';
            }
            return this;
        },
        
        css: function(property, value) {
            if (value === undefined) {
                return window.getComputedStyle(this[0]).getPropertyValue(property);
            } else {
                for (var i = 0; i < this.length; i++) {
                    this[i].style[property] = value;
                }
                return this;
            }
        },
        
        addClass: function(className) {
            for (var i = 0; i < this.length; i++) {
                this[i].classList.add(className);
            }
            return this;
        },
        
        removeClass: function(className) {
            for (var i = 0; i < this.length; i++) {
                this[i].classList.remove(className);
            }
            return this;
        },
        
        find: function(selector) {
            var result = new jQuery.fn.init();
            for (var i = 0; i < this.length; i++) {
                var elements = this[i].querySelectorAll(selector);
                for (var j = 0; j < elements.length; j++) {
                    result[result.length++] = elements[j];
                }
            }
            return result;
        },
        
        closest: function(selector) {
            var result = new jQuery.fn.init();
            for (var i = 0; i < this.length; i++) {
                var element = this[i];
                while (element && element.nodeType === 1) {
                    if (element.matches(selector)) {
                        result[result.length++] = element;
                        break;
                    }
                    element = element.parentNode;
                }
            }
            return result;
        },
        
        each: function(callback) {
            for (var i = 0; i < this.length; i++) {
                callback.call(this[i], i, this[i]);
            }
            return this;
        },
        
        attr: function(name, value) {
            if (value === undefined) {
                return this[0] ? this[0].getAttribute(name) : null;
            } else {
                for (var i = 0; i < this.length; i++) {
                    this[i].setAttribute(name, value);
                }
                return this;
            }
        },
        
        data: function(key, value) {
            if (!this.dataStore) this.dataStore = {};
            if (value === undefined) {
                return this.dataStore[key];
            } else {
                this.dataStore[key] = value;
                return this;
            }
        },
        
        empty: function() {
            for (var i = 0; i < this.length; i++) {
                while (this[i].firstChild) {
                    this[i].removeChild(this[i].firstChild);
                }
            }
            return this;
        },
        
        append: function(content) {
            for (var i = 0; i < this.length; i++) {
                if (typeof content === 'string') {
                    var div = document.createElement('div');
                    div.innerHTML = content;
                    while (div.firstChild) {
                        this[i].appendChild(div.firstChild);
                    }
                } else if (content.nodeType) {
                    this[i].appendChild(content);
                }
            }
            return this;
        }
    };
    
    jQuery.fn.init.prototype = jQuery.fn;
    
    // 模拟 e.stopPropagation
    window.Event.prototype.stopPropagation = function() {
        this.cancelBubble = true;
        if (this.stopPropagation) {
            this.stopPropagation();
        }
    };
    
    // 模拟 e.preventDefault
    window.Event.prototype.preventDefault = function() {
        this.returnValue = false;
        if (this.preventDefault) {
            this.preventDefault();
        }
    };
    
    // 模拟 e.which
    window.Event.prototype.which = function() {
        return this.keyCode || this.charCode;
    };
    
    window.jQuery = window.$ = jQuery;
})(window);